import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/ko/check-problem-list.png",g=JSON.parse('{"title":"설계 검사와 추천","description":"","frontmatter":{},"headers":[],"relativePath":"features/check.md","filePath":"features/check.md"}'),l={name:"features/check.md"};function i(n,t,s,c,h,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="설계-검사와-추천" tabindex="-1">설계 검사와 추천 <a class="header-anchor" href="#설계-검사와-추천" aria-label="Permalink to &quot;설계 검사와 추천&quot;">​</a></h1><p>그리는 동안 모델을 검사하는 설계 검사, 문제 목록에서 고치기·예외 두기, 입력 중 추천, 관계 이름 짝을 설명합니다.</p><p>빠른 시작의 <a href="/relio/quick/draw#알아-두면-좋은-것">테이블·컬럼·관계 그리기</a>에 짧은 소개가 있습니다.</p><h2 id="설계-검사" tabindex="-1">설계 검사 <a class="header-anchor" href="#설계-검사" aria-label="Permalink to &quot;설계 검사&quot;">​</a></h2><p>편집할 때마다 모델을 검사해 문제를 알려 줍니다. 어느 지적도 저장·내보내기를 막지 않습니다.</p><table tabindex="0"><thead><tr><th>심각도</th><th>뜻</th><th>캔버스 표시</th></tr></thead><tbody><tr><td>오류 ●</td><td>DDL을 실행하면 실패할 문제</td><td>테이블 머리 표시, 컬럼 줄 물결 밑줄</td></tr><tr><td>경고 ▲</td><td>고치는 게 좋은 문제</td><td>테이블 머리 표시, 컬럼 줄 물결 밑줄</td></tr><tr><td>참고 i</td><td>알아 두면 좋은 것</td><td>기본은 문제 목록에만</td></tr></tbody></table><ul><li>표시에 마우스를 올리면 내용이 나옵니다.</li><li>보기 › <strong>설계 검사 표시</strong>로 캔버스 표시 전체를 끄고 켭니다. 보기 › <strong>참고도 캔버스에 표시</strong>를 켜면 참고도 캔버스에 그립니다.</li><li>카테고리 탭 줄 오른쪽 끝의 <strong>문제: …</strong> 단추는 오류·경고 수만 세고(참고·예외로 숨긴 것은 빼고), 셀 것이 없으면 숨습니다. 누르면 문제 목록이 열립니다.</li><li>검사는 문서의 대상 DB·버전을 기준으로 합니다(예: 예약어, 이름 길이 상한). 대상 버전은 상태 표시줄 맨 왼쪽에서 바꿉니다.</li><li><kbd>F8</kbd> / <kbd>Shift</kbd>+<kbd>F8</kbd>로 다음·이전 지적으로 갑니다.</li></ul><h2 id="검사-규칙" tabindex="-1">검사 규칙 <a class="header-anchor" href="#검사-규칙" aria-label="Permalink to &quot;검사 규칙&quot;">​</a></h2><table tabindex="0"><thead><tr><th>규칙</th><th>규칙 ID</th><th>기본 심각도</th><th>무엇을 보나</th><th>고치기 단추</th></tr></thead><tbody><tr><td>기본 키 없음</td><td><code>pk-missing</code></td><td>경고</td><td>테이블에 기본 키(PK) 컬럼이 하나도 없음</td><td>정보 창 열기</td></tr><tr><td>외래 키에 인덱스 없음</td><td><code>fk-no-index</code></td><td>참고</td><td>외래 키(FK) 컬럼으로 시작하는 인덱스·기본 키·고유 키가 없음(MySQL·MariaDB 제외)</td><td>인덱스 만들기</td></tr><tr><td>참조 후보와 형식이 다름</td><td><code>fk-candidate-type</code></td><td>경고</td><td>관계 없는 컬럼이 다른 테이블 기본 키와 이름이 맞는데 형식이 다름</td><td>형식 맞추기</td></tr><tr><td>예약어 이름</td><td><code>reserved-word</code></td><td>오류</td><td>물리명이 대상 DB·버전의 예약어(테이블·뷰·컬럼·인덱스·시퀀스·트리거). 그 버전에서 실패할 수도 있는 정도면 참고</td><td></td></tr><tr><td>물리명 비어 있음</td><td><code>physical-name-empty</code></td><td>오류</td><td>테이블·뷰·컬럼의 물리명이 비어 있음</td><td>단어의 물리명 쓰기</td></tr><tr><td>형식 비어 있음</td><td><code>type-empty</code></td><td>오류</td><td>컬럼의 형식이 비어 있음</td><td></td></tr><tr><td>같은 이름 테이블</td><td><code>duplicate-table-name</code></td><td>오류</td><td>같은 스키마에 물리명이 같은 테이블·뷰·시퀀스</td><td></td></tr><tr><td>물리명에 쓸 수 없는 글자</td><td><code>physical-name-chars</code></td><td>오류</td><td>물리명에 공백·기호가 있거나 숫자로 시작(한글 등은 경고)</td><td></td></tr><tr><td>이름이 너무 김</td><td><code>identifier-too-long</code></td><td>오류</td><td>대상 DB·버전의 식별자 길이 상한을 넘음(PostgreSQL은 경고)</td><td></td></tr><tr><td>컬럼 없는 테이블</td><td><code>no-columns</code></td><td>오류</td><td>테이블에 컬럼이 없음</td><td></td></tr><tr><td>컬럼 이름 중복</td><td><code>duplicate-column-name</code></td><td>오류</td><td>한 테이블 안에 물리명이 같은 컬럼</td><td></td></tr><tr><td>논리명 중복</td><td><code>duplicate-logical-name</code></td><td>경고</td><td>문서 안에 논리명이 같은 테이블·뷰</td><td></td></tr><tr><td>SQL 없는 뷰</td><td><code>view-no-sql</code></td><td>오류</td><td>뷰에 SQL이 없음</td><td></td></tr><tr><td>지원하지 않는 전문 검색 인덱스</td><td><code>fulltext-unsupported</code></td><td>경고</td><td>전문 검색 인덱스는 MySQL·MariaDB에서만 쓸 수 있음</td><td></td></tr><tr><td>테이블스페이스 속성 없음</td><td><code>tablespace-no-properties</code></td><td>경고</td><td>테이블스페이스를 쓰는데 지금 환경의 속성이 비어 있음</td><td></td></tr></tbody></table><p>규칙 ID는 명령줄 <code>relio lint</code>의 <code>--disable</code> · <code>--only</code>에 씁니다. 기본 심각도는 환경 설정에서 바꾸기 전의 값이고, 괄호 안처럼 경우에 따라 다른 단계로 알리는 규칙도 있습니다.</p><p>&quot;단어의 물리명 쓰기&quot;는 비어 있는 물리명의 논리명과 같은 단어가 사전에 하나뿐일 때만 나타나고(외래 키 컬럼에는 나타나지 않습니다), 그 단어의 물리명을 채웁니다. 고치기 단추가 없는 지적은 항목을 두 번 눌러 정보 창에서 고칩니다. 규칙마다 켜고 끄기와 심각도는 <a href="/relio/features/preferences#설계-검사">환경 설정 › 설계 검사</a>에서 바꿉니다.</p><h2 id="문제-목록" tabindex="-1">문제 목록 <a class="header-anchor" href="#문제-목록" aria-label="Permalink to &quot;문제 목록&quot;">​</a></h2><p>아래 패널의 문제 목록(<kbd>Ctrl</kbd>+<kbd>J</kbd>, 보기 › 패널 ▸ › 아래 패널 (문제 목록))에 설계 검사 지적, 파일을 고쳐서 연 내역, DDL 내보내기 경고가 모입니다.</p><ul><li>심각도별로 켜고 끄고, <strong>대상·내용 찾기</strong> 칸으로 거르고, <strong>규칙별로 묶기</strong>로 규칙마다 모아 봅니다.</li><li>항목을 누르면 캔버스에서 그 객체로 가서 잠깐 강조하고, 두 번 누르면 정보 창이 열립니다. 지금 카테고리 탭에 없는 객체면 &quot;&#39;전체&#39; 탭에서 찾아 보세요&quot;라고 알립니다.</li><li>항목의 고치기 단추(예: <strong>인덱스 만들기</strong>, <strong>형식 맞추기</strong>)나 규칙 머리의 **모두 고치기: …**로 한 번에 고칩니다. 되돌리기 한 번으로 돌아갑니다.</li><li>참고 지적은 규칙마다 한 줄로 접혀 있고 누르면 펼쳐집니다.</li><li><kbd>Ctrl</kbd>·<kbd>Shift</kbd>로 여러 줄을 고르고 오른쪽 클릭하면 <strong>고른 것 모두 고치기</strong>, <strong>여기서 예외로</strong>, <strong>이 파일에서 &#39;…&#39; 끄기</strong>, <strong>목록 복사(Markdown)</strong>, <strong>CSV로 복사</strong>가 있습니다.</li><li>캔버스에서 노드·컬럼·선을 오른쪽 클릭하면 메뉴 맨 아래 **지적 (n) ▸**에서도 고치거나 예외로 둡니다.</li></ul><figure class="shot" data-scene="check-problem-list"><img src="'+a+'" alt="문제 목록 — 규칙별로 묶고 참고를 펼쳐 고치기 단추가 보이는 모습" loading="lazy"><figcaption>문제 목록 — 규칙별로 묶고 참고를 펼쳐 고치기 단추가 보이는 모습</figcaption></figure><h2 id="예외" tabindex="-1">예외 <a class="header-anchor" href="#예외" aria-label="Permalink to &quot;예외&quot;">​</a></h2><ul><li><strong>여기서 예외로</strong> — 그 지적 하나를 숨깁니다.</li><li><strong>이 파일에서 &#39;…&#39; 끄기</strong> — 그 규칙을 이 파일에서 끕니다.</li><li>예외는 <code>.erm</code>이 아니라 이 PC의 앱 설정에 파일별로 기록됩니다. 문서가 &quot;변경됨&quot;이 되지 않고, 팀과 나눠지지 않습니다.</li><li>문제 목록의 <strong>예외 보기</strong>에서 예외를 보고 <strong>예외 풀기</strong>로 다시 엽니다. 대상이 없어진 예외는 <strong>대상 없는 예외 지우기</strong>로 정리합니다.</li></ul><div class="info custom-block"><p class="custom-block-title">참고</p><p>명령줄 <code>relio lint</code>는 이 PC의 예외를 쓰지 않아 어느 PC에서나 같은 결과를 냅니다. CI에서 끌 규칙은 <code>--disable</code>로 지정합니다. <a href="/relio/features/cli#relio-lint">명령줄 › relio lint</a></p></div><h2 id="입력하는-자리에서-알림" tabindex="-1">입력하는 자리에서 알림 <a class="header-anchor" href="#입력하는-자리에서-알림" aria-label="Permalink to &quot;입력하는 자리에서 알림&quot;">​</a></h2><ul><li>테이블·컬럼 정보 창은 칸 아래 한 줄로 물리명 비어 있음·같은 이름 테이블·한글·공백·예약어·형식 비어 있음을 알려 줍니다(막지 않음).</li><li>새 컬럼 창은 아직 손대지 않은 칸의 알림을 미뤘다가, 그 칸에 치거나 한 번 지나간 뒤에 보입니다.</li><li>DDL 내보내기 창은 &quot;이 문서에 DDL 실행을 실패하게 하는 오류가 n개 있습니다&quot;를 보여 줍니다. <a href="/relio/features/ddl">DDL</a></li></ul><h2 id="입력-중-추천" tabindex="-1">입력 중 추천 <a class="header-anchor" href="#입력-중-추천" aria-label="Permalink to &quot;입력 중 추천&quot;">​</a></h2><p>컬럼 정보 창에서 물리명·논리명을 치면 단어 사전과 다른 테이블의 컬럼에서 후보가 나옵니다.</p><ul><li>목록은 칸 <strong>위</strong>에 열려 아래 칸을 가리지 않습니다. 후보는 최대 8개입니다.</li><li><kbd>↓</kbd> / <kbd>↑</kbd>로 고르고 <kbd>Enter</kbd>·<kbd>Tab</kbd>으로 받으면 이름·형식·길이·논리명이 한 번에 채워집니다. 줄을 마우스로 눌러도 받습니다.</li><li><kbd>↓</kbd>로 고르지 않고 누른 <kbd>Enter</kbd>는 후보를 받지 않습니다. 마우스를 올린 줄도 고른 것이 아닙니다.</li><li>잘못 받았으면 <strong>채우기 취소</strong>를 누릅니다.</li></ul><h2 id="관계-이름-짝" tabindex="-1">관계 이름 짝 <a class="header-anchor" href="#관계-이름-짝" aria-label="Permalink to &quot;관계 이름 짝&quot;">​</a></h2><ul><li>1:N 관계 도구로 부모 테이블을 누르면, 이름이 맞는 컬럼이 있는 자식 후보 테이블이 강조됩니다(&quot;이름이 맞는 후보 n개 강조됨&quot;).</li><li>관계를 만든 뒤 자식에 같은 이름 컬럼이 둘이 되면 알림 띠가 뜹니다. <strong>기존 컬럼을 외래 키로 쓰기</strong>를 누르면 원래 있던 컬럼을 외래 키로 쓰도록 한 번에 바꿉니다(형식은 부모를 따라 바뀝니다). <strong>그대로 두기</strong>로 닫습니다.</li></ul><p>입력 중 추천·관계 이름 짝·캔버스 표시는 <a href="/relio/features/preferences#설계-검사">환경 설정 › 설계 검사</a>에서 끌 수 있습니다.</p>',26)])])}const p=d(l,[["render",i]]);export{g as __pageData,p as default};
